    Named* rec::lookup(instanceLookup* l, Named* inst)
    {
        for(auto [gocpp_ignored, t] : l->buf)
        {
            if(t != nullptr && Identical(inst, t))
            {
                return t;
            }
        }
        for(auto [gocpp_ignored, t] : l->m[rec::Origin(gocpp::recv(inst))])
        {
            if(Identical(inst, t))
            {
                return t;
            }
        }
        return nullptr;
    }

    void rec::add(instanceLookup* l, Named* inst)
    {
        for(auto [i, t] : l->buf)
        {
            if(t == nullptr)
            {
                l->buf[i] = inst;
                return;
            }
        }
        if(l->m == nullptr)
        {
            l->m = gocpp::make(gocpp::Tag<gocpp::map<Named*, gocpp::slice<Named*>>>());
        }
        auto insts = l->m[rec::Origin(gocpp::recv(inst))];
        l->m[rec::Origin(gocpp::recv(inst))] = append(insts, inst);
    }

